"""Authentic local vLLM capture -> explicitly derived native Miles SessionRecords.

The original wire response stays untouched. vLLM supplies exact IDs and log
probabilities, but no native generation weight revision. Static checkpoint and
process identity is verified by the owner before and after each generation.
The Miles compatibility projection names that distinction in every sample.
This module never tokenizes historical text or authorizes weight updates.
"""
from __future__ import annotations

import hashlib
import json
from copy import deepcopy
from pathlib import Path

from ndfeb_sps.miles_investigation import (
    _hash,
    _number,
    _require,
    _token_ids,
    attach_terminal_reward,
    build_miles_investigation,
    capture_sha256,
    validate_investigation_capture,
    validate_policy_identity,
)

SCHEMA = "ndfeb-vllm-investigation-v1"
IDENTITY_ORIGIN = "owner_verified_static_runtime_not_native_weight_version"


def project_vllm_capture(bundle, *, expected_policy, allow_test_fixtures=False):
    """Verify native bytes, then derive only fields required by pinned Miles.

    Returning a compatibility projection is not evidence that SGLang served the
    policy, nor that vLLM itself authenticated weights. Original hashes and both
    guard receipts remain attached. Frozen FP8 study admission is not implied.
    """
    _require(bundle.get("schema") == SCHEMA, "Expected original vLLM capture schema")
    fixture = bundle.get("origin") == "explicit_test_fixture"
    _require(bundle.get("origin") == "fresh_interactive" or (fixture and allow_test_fixtures),
             "Only native interactive capture; fixtures require explicit opt-in")
    validate_policy_identity(bundle.get("policy_identity"), expected_policy)
    _require(expected_policy.get("weight_identity_origin") == IDENTITY_ORIGIN,
             "vLLM requires truthful owner-bound static identity")
    _require(bundle.get("deployment_identity_origin") == IDENTITY_ORIGIN,
             "Do not mislabel vLLM metadata as native weight version")
    runtime = bundle.get("runtime_identity_sha256")
    _require(_hash(runtime), "Missing immutable runtime identity")
    _require(isinstance(bundle.get("turns"), list) and bundle["turns"], "Missing original turns")
    projected = deepcopy(bundle)
    projected["schema"] = "ndfeb-miles-investigation-v1"
    projected["compatibility_projection"] = {
        "schema": "ndfeb-vllm-to-miles-session-record-v1",
        "raw_capture_sha256": capture_sha256(bundle),
        "weight_version_origin": IDENTITY_ORIGIN,
        "tokens_origin": "untouched_native_vllm_response",
        "retokenization_performed": False,
        "training_admission": "local_nvfp4_diagnostic_only_not_frozen_fp8_policy",
    }
    for raw_turn, turn in zip(bundle["turns"], projected["turns"], strict=True):
        record = raw_turn.get("record", {})
        raw = record.get("response", {})
        request = record.get("request", {})
        _require(raw_turn.get("response_sha256") == capture_sha256(raw), "Original response hash mismatch")
        _require(raw_turn.get("request_sha256") == capture_sha256(request), "Original request hash mismatch")
        _require(isinstance(raw.get("id"), str) and raw["id"], "Missing native response identity")
        _require(raw.get("model") == request.get("model"), "Native served model changed")
        _require(isinstance(raw.get("choices"), list) and len(raw["choices"]) == 1,
                 "Exactly one native output is required")
        choice = raw["choices"][0]
        _require(choice.get("index") == 0, "Native choice index changed")
        prompt, output = raw.get("prompt_token_ids"), choice.get("token_ids")
        _require(_token_ids(prompt) and _token_ids(output), "Missing native vLLM prompt/output IDs")
        _require(request.get("input_ids") == prompt, "Prompt IDs disagree with original native response")
        _require(request.get("return_token_ids") is True
                 and request.get("return_tokens_as_token_ids") is True
                 and request.get("logprobs") is True, "Request did not request exact native token evidence")
        _require(not choice.get("routed_experts"), "Expert-routing replay has not been qualified")
        logs = choice.get("logprobs", {}).get("content")
        _require(isinstance(logs, list) and len(logs) == len(output), "Missing native sampled logprobs")
        for token, log in zip(output, logs, strict=True):
            _require(log.get("token") == f"token_id:{token}", "Native sampled ID/logprob misalignment")
            _require(_number(log.get("logprob")) and -9999 < log["logprob"] <= 0,
                     "Invalid/missing/clamped native log probability")
        usage = raw.get("usage", {})
        _require(usage.get("prompt_tokens") == len(prompt)
                 and usage.get("completion_tokens") == len(output)
                 and usage.get("total_tokens") == len(prompt) + len(output), "Native usage mismatch")
        binding = raw_turn.get("deployment_binding", {})
        _require(binding.get("origin") == IDENTITY_ORIGIN, "Missing static deployment binding")
        for stage in ("before", "after"):
            guard = binding.get(stage, {})
            _require(guard.get("schema") == "ndfeb-vllm-static-runtime-guard-v1"
                     and guard.get("valid") is True
                     and guard.get("runtime_identity_sha256") == runtime
                     and guard.get("speculative_decoding") is False
                     and guard.get("hot_updates_disabled") is True,
                     "Runtime guard missing, changed, or unqualified")
            _require(fixture or guard.get("origin") != "explicit_test_fixture",
                     "Fixture guard cannot authenticate live model")
        for kind in ("request", "response"):
            _require(_hash(raw_turn.get(f"wire_{kind}_sha256")), "Missing wire hash")
            filename = raw_turn.get(f"wire_{kind}_file")
            if not fixture or filename:
                _require(isinstance(filename, str) and Path(filename).is_absolute(), "Missing original wire file")
                wire_bytes = Path(filename).read_bytes()
                _require(hashlib.sha256(wire_bytes).hexdigest() == raw_turn[f"wire_{kind}_sha256"],
                         "Original wire bytes changed")
                wire = json.loads(wire_bytes)
                expected = raw if kind == "response" else {k: v for k, v in request.items() if k != "input_ids"}
                _require(wire == expected, "Retained wire record was altered")
        # These are documented compatibility fields, not server-returned metadata.
        derived = turn["record"]["response"]["choices"][0]
        _require("meta_info" not in derived, "Unexpected native SGLang metadata in vLLM response")
        derived["prompt_token_ids"] = deepcopy(prompt)
        derived["response_token_ids"] = deepcopy(output)
        derived["meta_info"] = {
            "completion_tokens": len(output),
            "output_token_logprobs": [[log["logprob"], token, None] for token, log in zip(output, logs, strict=True)],
            "weight_version": expected_policy["weight_version"],
            "weight_version_origin": IDENTITY_ORIGIN,
            "compatibility_projection": True,
        }
        turn["native_vllm_response_sha256"] = raw_turn["response_sha256"]
        turn["response_sha256"] = capture_sha256(turn["record"]["response"])
    # Reuse established chronology, tool-observation, compaction, completion and
    # full-model checks on the explicit compatibility representation.
    audit = validate_investigation_capture(projected, expected_policy=expected_policy,
                                           allow_test_fixtures=allow_test_fixtures)
    audit.update({"native_provider": "vllm", "raw_capture_sha256": capture_sha256(bundle),
                  "weight_identity_origin": IDENTITY_ORIGIN, "retokenization_performed": False,
                  "frozen_fp8_study_eligible": False})
    return projected, audit


def build_vllm_investigation(bundle, tokenizer, *, expected_policy, allow_test_fixtures=False):
    projected, audit = project_vllm_capture(bundle, expected_policy=expected_policy,
                                          allow_test_fixtures=allow_test_fixtures)
    samples, assembly = build_miles_investigation(projected, tokenizer, expected_policy=expected_policy,
                                                  allow_test_fixtures=allow_test_fixtures)
    audit["native_miles_assembly"] = assembly
    for sample, turn in zip(samples, bundle["turns"], strict=True):
        sample.metadata.update({
            "native_provider": "vllm", "native_response_sha256": turn["response_sha256"],
            "raw_capture_sha256": audit["raw_capture_sha256"],
            "weight_identity_origin": IDENTITY_ORIGIN,
            "deployment_binding": deepcopy(turn["deployment_binding"]),
            "compatibility_projection": deepcopy(projected["compatibility_projection"]),
            "frozen_fp8_study_eligible": False,
            "training_admission": "local_nvfp4_diagnostic_only; no updates authorized",
        })
    return samples, audit


def main(argv=None):
    import argparse

    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--capture", type=Path, required=True)
    parser.add_argument("--policy", type=Path, required=True)
    parser.add_argument("--tokenizer", type=Path, required=True)
    parser.add_argument("--output", type=Path, required=True)
    parser.add_argument("--assessment", type=Path)
    parser.add_argument("--reward-contract", type=Path)
    args = parser.parse_args(argv)
    _require(not args.output.exists(), "Refusing to overwrite assembly")
    from transformers import AutoTokenizer

    bundle = json.loads(args.capture.read_text())
    policy = json.loads(args.policy.read_text())
    tokenizer = AutoTokenizer.from_pretrained(args.tokenizer, local_files_only=True, trust_remote_code=False)
    samples, audit = build_vllm_investigation(bundle, tokenizer, expected_policy=policy)
    _require(bool(args.assessment) == bool(args.reward_contract), "Assessment and reward contract must be provided together")
    reward = None
    if args.assessment:
        assessment = json.loads(args.assessment.read_text())
        reward = assessment.get("result", assessment).get("reward")
        _require(_number(reward), "Independent assessment has no finite optimization label")
        attach_terminal_reward(samples, terminal_reward=reward,
                               reward_receipt_sha256=hashlib.sha256(args.assessment.read_bytes()).hexdigest(),
                               reward_contract_sha256=hashlib.sha256(args.reward_contract.read_bytes()).hexdigest())
        for sample in samples:
            sample.metadata["training_admission"] = "local_nvfp4_diagnostic_only; no updates authorized"
            type(sample).from_dict(sample.to_dict()).validate()
    result = {"schema": "ndfeb-vllm-native-miles-assembly-v1", "audit": audit,
              "capture_file_sha256": hashlib.sha256(args.capture.read_bytes()).hexdigest(),
              "samples": [sample.to_dict() for sample in samples], "weight_updates": 0,
              "reward_supplied": args.assessment is not None, "reward": reward,
              "assessment_path": str(args.assessment) if args.assessment else None,
              "training_admission": False, "frozen_fp8_study_eligible": False}
    args.output.parent.mkdir(parents=True, exist_ok=True)
    with args.output.open("x") as file:
        json.dump(result, file, indent=2, allow_nan=False)
        file.write("\n")
    print(json.dumps({"status": "assembled_no_update", "turns": len(samples), "output": str(args.output)}))


if __name__ == "__main__":
    main()
